const updateWorkflowDebugPolicy = `-- name: UpdateWorkflowDebugPolicy :one
UPDATE workflow_debug_policy SET enabled = $2, user_active_runs = $3, workspace_active_runs = $4,
 user_starts_per_hour = $5, max_duration_seconds = $6, retention_seconds = $7, payload_capacity_bytes = $8,
 updated_by = $9, updated_at = now(), revision = revision + 1
WHERE workspace_id = $1 AND revision = $10 RETURNING workspace_id, revision, enabled, user_active_runs, workspace_active_runs, user_starts_per_hour, max_duration_seconds, retention_seconds, payload_capacity_bytes, updated_by, updated_at
`

type UpdateWorkflowDebugPolicyParams struct {
	WorkspaceID          pgtype.UUID `json:"workspace_id"`
	Enabled              bool        `json:"enabled"`
	UserActiveRuns       int32       `json:"user_active_runs"`
	WorkspaceActiveRuns  int32       `json:"workspace_active_runs"`
	UserStartsPerHour    int32       `json:"user_starts_per_hour"`
	MaxDurationSeconds   int32       `json:"max_duration_seconds"`
	RetentionSeconds     int32       `json:"retention_seconds"`
	PayloadCapacityBytes int64       `json:"payload_capacity_bytes"`
	UpdatedBy            pgtype.UUID `json:"updated_by"`
	ExpectedRevision     int64       `json:"expected_revision"`
}

func (q *Queries) UpdateWorkflowDebugPolicy(ctx context.Context, arg UpdateWorkflowDebugPolicyParams) (WorkflowDebugPolicy, error) {
	row := q.db.QueryRow(ctx, updateWorkflowDebugPolicy,
		arg.WorkspaceID,
		arg.Enabled,
		arg.UserActiveRuns,
		arg.WorkspaceActiveRuns,
		arg.UserStartsPerHour,
		arg.MaxDurationSeconds,
		arg.RetentionSeconds,
		arg.PayloadCapacityBytes,
		arg.UpdatedBy,
		arg.ExpectedRevision,
	)
	var i WorkflowDebugPolicy
	err := row.Scan(
		&i.WorkspaceID,
		&i.Revision,
		&i.Enabled,
		&i.UserActiveRuns,
		&i.WorkspaceActiveRuns,
		&i.UserStartsPerHour,
		&i.MaxDurationSeconds,
		&i.RetentionSeconds,
		&i.PayloadCapacityBytes,
		&i.UpdatedBy,
		&i.UpdatedAt,
	)
	return i, err
}

